package com.bank.gitops;

public class DesiredState {
    private final String image;
    private final int replicas;

    public DesiredState(String image, int replicas) {
        this.image = image;
        this.replicas = replicas;
    }

    public String getImage() { return image; }
    public int getReplicas() { return replicas; }

    @Override public String toString() { return "image=" + image + ", replicas=" + replicas; }

    @Override public boolean equals(Object o) {
        if (!(o instanceof DesiredState)) return false;
        DesiredState d = (DesiredState) o;
        return replicas == d.replicas && image.equals(d.image);
    }
    @Override public int hashCode() { return image.hashCode() * 31 + replicas; }
}
