package com.bank.gitops;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Single source of truth. Each change is a "commit" with author + message.
public class GitRepo {
    private static final Logger log = Logger.getLogger(GitRepo.class.getName());
    private final List<String> history = new ArrayList<>();
    private DesiredState current;

    public GitRepo(DesiredState initial, String author) {
        this.current = initial;
        commit(author, "initial: " + initial);
    }

    public void commit(String author, String message) {
        history.add(author + " | " + message);
        log.info(() -> "GIT COMMIT by " + author + " — " + message);
    }

    public void update(DesiredState next, String author, String message) {
        this.current = next;
        commit(author, message + " → " + next);
    }

    public DesiredState getDesired() { return current; }
    public List<String> getHistory() { return history; }
}
