package com.bank.gitops;

import java.util.logging.Logger;

public class Cluster {
    private static final Logger log = Logger.getLogger(Cluster.class.getName());
    private DesiredState live;

    public Cluster(DesiredState initial) { this.live = initial; }

    public DesiredState getLive() { return live; }

    public void apply(DesiredState s) {
        log.info(() -> "CLUSTER apply → " + s);
        this.live = s;
    }

    // Simulate someone running kubectl edit by hand (causes drift).
    public void manualEdit(DesiredState drifted) {
        log.warning(() -> "MANUAL kubectl edit (drift!) → " + drifted);
        this.live = drifted;
    }
}
