package com.bank.gitops;

import java.util.logging.Logger;

// Reconciles cluster to Git on a loop: detects drift, applies desired state.
public class GitOpsOperator {
    private static final Logger log = Logger.getLogger(GitOpsOperator.class.getName());
    private final GitRepo repo;
    private final Cluster cluster;
    private final boolean selfHeal;

    public GitOpsOperator(GitRepo repo, Cluster cluster, boolean selfHeal) {
        this.repo = repo;
        this.cluster = cluster;
        this.selfHeal = selfHeal;
    }

    // One reconciliation pass. Returns true if it had to correct drift.
    public boolean reconcile() {
        DesiredState desired = repo.getDesired();
        DesiredState live = cluster.getLive();
        if (desired.equals(live)) {
            log.fine(() -> "In sync: " + desired);
            return false;
        }
        log.warning(() -> "OUT OF SYNC — desired=" + desired + " live=" + live);
        if (selfHeal) {
            cluster.apply(desired);
            log.info("Self-healed cluster back to Git desired state.");
            return true;
        }
        log.warning("selfHeal disabled — leaving drift (NOT recommended).");
        return false;
    }
}
