package com.bank.gitops;

import java.util.logging.*;

public class GitOpsDemo {
    private static final Logger log = Logger.getLogger(GitOpsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DesiredState v42 = new DesiredState("transfer-service:4.2.0", 3);
        GitRepo repo = new GitRepo(v42, "rajesh");
        Cluster cluster = new Cluster(v42);
        GitOpsOperator operator = new GitOpsOperator(repo, cluster, true);

        log.info("=== Initial reconcile (already in sync) ===");
        operator.reconcile();

        log.info("=== Someone edits the cluster by hand (drift) ===");
        cluster.manualEdit(new DesiredState("transfer-service:4.2.0", 1)); // scaled down by hand
        operator.reconcile();   // operator reverts it to replicas=3

        log.info("=== Deploy v4.3.0 the GitOps way (commit, then sync) ===");
        repo.update(new DesiredState("transfer-service:4.3.0", 3), "priya",
            "deploy v4.3.0 (PR #214 reviewed)");
        operator.reconcile();   // operator rolls out the new image

        log.info("=== Rollback = revert the commit ===");
        repo.update(v42, "priya", "revert to v4.2.0 (PR #215, latency regression)");
        operator.reconcile();   // operator restores v4.2.0

        log.info(() -> "Git history (full audit trail): " + repo.getHistory());
    }
}
